-- =============================================================================
-- 463 — LE CAHIER D'EXERCICES DE 3E (partie 7)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 463 --niveau 3e --fichiers technologie.m1,technologie.m2 --suffixe 7 > supabase/contenu/463_exercices_3e_7.sql
--
-- 69 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   technologie.m1          36 exercices · 12 chapitres
--   technologie.m2          33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('7b9cf9f2-dd75-52e8-b501-e03af97cdc28'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les OST du collège","competence":"analyser-document","situation":"Le professeur de technologie fait l’inventaire de quelques objets que l’on croise au collège. Il veut les ranger : objet technique seul, ou système technique ?","documents":[{"id":"inv","type":"tableau","titre":"Quatre OST du collège","colonnes":["Objet","Service rendu","De quoi est-il fait ?"],"lignes":[["Tournevis","Visser et dévisser","Un seul objet"],["Alarme incendie","Prévenir en cas de fumée","Détecteurs, centrale, sirène, programme"],["Chaise","S’asseoir","Un seul objet"],["Portail automatisé","Ouvrir et fermer l’entrée","Moteur, carte électronique, capteurs"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux **systèmes techniques** du tableau (touche leur nom).","aide":"Un système technique associe plusieurs objets qui travaillent ensemble.","type":"zone","document":"inv","multiple":true},{"enonce":"Combien d’objets techniques « seuls » le tableau contient-il ?","aide":"Compte les lignes où la dernière colonne dit « Un seul objet ».","type":"nombre"},{"enonce":"Complète la définition d’un OST.","aide":"Pense à ce qui justifie l’existence de l’objet.","type":"trous","segments":["Un OST est un objet conçu et fabriqué par l’",0," pour satisfaire un ",1,"."],"banque":["hasard","prix","besoin","homme","animal"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r3c0"]},"explication":"L’**alarme incendie** et le **portail automatisé** réunissent plusieurs éléments, avec de l’électronique et un programme."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Le **tournevis** et la **chaise** : 2 objets, chacun répond au besoin par lui-même."},{"cle":{"type":"trous","trous":[["homme","etre humain","humain"],["besoin"]]},"affichage":"homme · besoin","explication":"Un OST est conçu par l’**homme** pour satisfaire un **besoin**."}]$ex$::jsonb),
  ('7b9cf9f2-dd75-52e8-b501-e03af97cdc28'::uuid, 2, 2, 10, 35, 4,
