gs ?","aide":"Compare avec les blocs.","type":"choix","options":[{"id":"a","texte":"Elle remplace l’algorithme"},{"id":"b","texte":"Elle n’a pas de limite de taille et se partage facilement"},{"id":"c","texte":"Elle supprime toute erreur"},{"id":"d","texte":"Elle ne demande aucune syntaxe"}],"multiple":false}]}$ex$::jsonb,
