er avant toute fabrication"}],"multiple":false},{"enonce":"Un dessin technique est…","aide":"Concepteur et fabricant doivent se comprendre.","type":"choix","options":[{"id":"a","texte":"un croquis rapide"},{"id":"b","texte":"un document contractuel, lu de la même façon par tous"},{"id":"c","texte":"une photographie"},{"id":"d","texte":"un joli dessin d’artiste"}],"multiple":false}]}$ex$::jsonb,
